# -*- coding: utf-8 -*-
from .base import LanguageModule, FrameworkPack, LanguageBranch, BestPractice, sec, eng
SECURITY=[sec('PHP-SEC-SQLI-01','SQL variable','critical',r'(?:mysqli_query|->query)\s*\([^)]*\$','SQL injection.','PDO prepared statements',cwe='CWE-89'),sec('PHP-SEC-CMDI-01','Shell execution','critical',r'\b(?:exec|system|shell_exec|passthru)\s*\([^)]*\$','Command injection.','Validate and escape',cwe='CWE-78'),sec('PHP-SEC-EVAL-01','eval','critical',r'\beval\s*\(','Dynamic code.','Avoid eval',cwe='CWE-95'),sec('PHP-SEC-DESER-01','unserialize','critical',r'\bunserialize\s*\(','Unsafe deserialization.','Use JSON',cwe='CWE-502'),sec('PHP-SEC-XSS-01','Unescaped echo','high',r'echo\s+\$_(?:GET|POST|REQUEST)','XSS.','htmlspecialchars',cwe='CWE-79'),sec('PHP-SEC-SECRET-01','Hardcoded secret','high',r'(?:password|secret|token)\s*=\s*["\'][^"\']{5,}["\']','Secret.','Use getenv',cwe='CWE-798'),sec('PHP-SEC-PATH-01','File input path','high',r'(?:readfile|file_get_contents|include)\s*\([^)]*\$_(?:GET|POST)','Path traversal.','Validate basename',cwe='CWE-22')]
ENGINEERING=[eng('PHP-ENG-TODO','TODO','info',r'//\s*TODO','Marker.','Create issue'),eng('PHP-ENG-DIE','die/exit','low',r'\b(?:die|exit)\s*\(','Abrupt termination.','Return structured error')]
FRAME=FrameworkPack('Laravel','10.x','https://laravel.com/docs',[sec('PHP-LARAVEL-01','Raw DB query','high',r'DB::raw\s*\(','Raw query.','Use bindings',cwe='CWE-89')])
LANGUAGE=LanguageModule('php','8.2+',['.php'],'PHP knowledge base','https://www.php.net/docs.php',SECURITY,ENGINEERING,[FRAME],[LanguageBranch('web','Web apps',['XSS','SQLi'],['SQLi'],['PHP-SEC-SQLI-01'])],[BestPractice('Escape output','Escape HTML output.','htmlspecialchars($x)','echo $x')])
